    static let hc_mix_inject = #"""
// P020 unit 10: the hyper-connection MIX and the INJECT logits in one pass.
//   mixed[row, j] = mean_h( sigmoid(u[row, h*D + j]) * normed[row, h*D + j] )
//   inj[row, c]   = sum_i normed[row, i] * winj[c, i]                 (the block_inject_weight Linear)
// Both read the SAME 84 MB `normed` at a 4096-row chunk; separately that is two full passes over it
// (the mix kernel and MLX's qmv for the inject). One threadgroup per ROWS rows, TG threads: every
// element of `normed` is read once and used for both. The inject weight is 4 x 10240 bf16 = 80 KB and
// is read once per threadgroup, so ROWS > 1 amortises it.
// normed/u [rows, H*D] T, winj [H, H*D] T -> mixed [rows, D] T, inj [rows, H] T
// template T, H, D, TG, ROWS.  grid ceil(rows/ROWS)*TG threads, threadgroup TG.
uint tg = threadgroup_position_in_grid.x;
uint tid = thread_position_in_threadgroup.x;
constexpr int PER = D / TG;
threadgroup float part[H][32];
float injacc[ROWS][H];
for (int r = 0; r < ROWS; ++r)
    for (int c = 0; c < H; ++c) injacc[r][c] = 0.0f;

for (int r = 0; r < ROWS; ++r) {
    uint row = tg * ROWS + r;
    if (row >= uint(NROWS)) break;
    ulong base = (ulong)row * (ulong)(H * D);
    for (int i = 0; i < PER; ++i) {
        uint j = tid + TG * i;
        float acc = 0.0f;
        for (uint h = 0; h < H; ++h) {
            float nv = float(normed[base + h * D + j]);
            float uu = float(u[base + h * D + j]);
            acc += (1.0f / (1.0f + exp(-uu))) * nv;
            for (int c = 0; c < H; ++c) injacc[r][c] += nv * float(winj[(ulong)c * (H * D) + h * D + j]);
        }
        mixed[(ulong)row * D + j] = T(acc / float(H));
    }
}
for (int r = 0; r < ROWS; ++r) {
    uint row = tg * ROWS + r;
    if (row >= uint(NROWS)) break;
    for (int c = 0; c < H; ++c) {
        float v = simd_sum(injacc[r][c]);
        if (thread_index_in_simdgroup == 0) part[c][simdgroup_index_in_threadgroup] = v;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < H) {
        float tot = 0.0f;
        for (int s = 0; s < TG / 32; ++s) tot += part[tid][s];
