float acc = 0.0f;
for (int k4 = 0; k4 < R / 4; ++k4) {
    float4 wv = float4(wr[k4]);
    const threadgroup float* sp = sd + k4 * 4;
    acc += sp[0] * wv.x + sp[1] * wv.y + sp[2] * wv.z + sp[3] * wv.w;
