    dq += sp[4] * float(q4.y & 0xffu) + sp[5] * float((q4.y >> 8) & 0xffu) + sp[6] * float((q4.y >> 16) & 0xffu) + sp[7] * float(q4.y >> 24);
    dq += sp[8] * float(q4.z & 0xffu) + sp[9] * float((q4.z >> 8) & 0xffu) + sp[10] * float((q4.z >> 16) & 0xffu) + sp[11] * float(q4.z >> 24);
    dq += sp[12] * float(q4.w & 0xffu) + sp[13] * float((q4.w >> 8) & 0xffu) + sp[14] * float((q4.w >> 16) & 0xffu) + sp[15] * float(q4.w >> 24);
    int g = (blk * 16) / GS;
    acc += float(sr[g]) * dq + float(br[g]) * sd16[blk];
}
for (int o = 1; o < KS; o <<= 1) acc += simd_shuffle_xor(acc, o);
float nv = float(normed[(ulong)row * (H * D) + idx]);
float p = nv / (1.0f + exp(-acc));
for (int o = KS; o < KS * H; o <<= 1) p += simd_shuffle_xor(p, o);
if (h == 0 && kq == 0) mixed[(ulong)row * D + jp] = T(p / float(H));
float c[H];
for (int hh = 0; hh < H; ++hh) { float wv = (kq == 0) ? nv * float(winj[(ulong)hh * (H * D) + idx]) : 0.0f; c[hh] = simd_sum(wv); }
if (thread_index_in_simdgroup == 0) for (int hh = 0; hh < H; ++hh) part[simdgroup_index_in_threadgroup][hh] = c[hh];
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < uint(H)) {
    float s = 0.0f;
    for (int i = 0; i < TGS / 32; ++i) s += part[i][tid];
    uint tgp = threadgroup_position_in_grid.x % PT;
    injp[((ulong)row * PT + tgp) * H + tid] = s;
}

"""#
    static let hc_up_mix_ni = #"""
// hyper-connection tail with the grouped norm applied on the fly: `normed` is replaced by (out, w1, sqp, epsv):
//   normed[h*D + j] = T(out[h*D + j] * inv[h] * w1[h*D + j]),  inv[h] = rsqrt(sum_p sqp[(row*H+h)*PQ+p] / D + eps).  template adds PQ.
// hyper-connection tail in one kernel. Per row:
//   sd[k]   = silu(down[k] / H)                                   k < R   (threadgroup-shared)
//   u[i]    = sum_k sd[k] * (s*q + b)[i, k]                       i < H*D  (8-bit affine, group GS, K = R)
//   mixed[j] = mean_h sigmoid(u[h*D + j]) * normed[h*D + j]      j < D
//   injp[row, tg, hh] = partial sum over this threadgroup of normed[i] * winj[hh, i]   (P = H*D/256 partials per row)
// grid: rows * H * D threads, threadgroup TGS (P = H*D/TGS partials per row); thread t -> row, jp = (t % (H*D)) / H, h = t % H (h fastest).
// template T, H, D, R, GS, TGS, DS.  down: [rows, R] (DS = 1) or [rows, DS, R] split-K partials, any float dtype; hcf: float[1] = H.
uint t = thread_position_in_grid.x;
uint tid = thread_index_in_threadgroup;
uint row = t / (H * D), rem = t % (H * D), jp = rem / H, h = rem % H;
constexpr int NG = R / GS;
threadgroup float sd[R];
threadgroup float sdsum[NG];
threadgroup float part[TGS / 32][H];
for (uint k = tid; k < uint(R); k += TGS) {
    float v = 0.0f;
    for (int s = 0; s < DS; ++s) v += float(down[((ulong)row * DS + s) * R + k]);   // DS split-K partials of the down projection (DS = 1: plain [rows, R])
    v /= hcf[0];
    sd[k] = v / (1.0f + exp(-v));
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < uint(NG)) { float s = 0.0f; for (int k = 0; k < GS; ++k) s += sd[tid * GS + k]; sdsum[tid] = s; }
threadgroup_barrier(mem_flags::mem_threadgroup);
uint idx = h * D + jp;                                           // u index in [0, H*D)
const device uint4* wr = (const device uint4*)(uw + (ulong)idx * (R / 4));
const device T* sr = us + (ulong)idx * NG;
const device T* br = ub + (ulong)idx * NG;
float acc = 0.0f;
for (int g = 0; g < NG; ++g) {
    float dq = 0.0f;
    for (int q4i = 0; q4i < GS / 16; ++q4i) {
        uint4 q4 = wr[g * (GS / 16) + q4i];
        const threadgroup float* sp = sd + g * GS + q4i * 16;
        dq += sp[0] * float(q4.x & 0xffu) + sp[1] * float((q4.x >> 8) & 0xffu) + sp[2] * float((q4.x >> 16) & 0xffu) + sp[3] * float(q4.x >> 24);
        dq += sp[4] * float(q4.y & 0xffu) + sp[5] * float((q4.y >> 8) & 0xffu) + sp[6] * float((q4.y >> 16) & 0xffu) + sp[7] * float(q4.y >> 24);
        dq += sp[8] * float(q4.z & 0xffu) + sp[9] * float((q4.z >> 8) & 0xffu) + sp[10] * float((q4.z >> 16) & 0xffu) + sp[11] * float(q4.z >> 24);
        dq += sp[12] * float(q4.w & 0xffu) + sp[13] * float((q4.w >> 8) & 0xffu) + sp[14] * float((q4.w >> 16) & 0xffu) + sp[15] * float(q4.w >> 24);
    }
    acc += float(sr[g]) * dq + float(br[g]) * sdsum[g];
}
float ssq = 0.0f;
for (int p = 0; p < PQ; ++p) ssq += sqp[((ulong)row * H + h) * PQ + p];
float invh = rsqrt(ssq / float(D) + epsv[0]);
float nv = float(T(float(out[(ulong)row * (H * D) + idx]) * invh * float(w1[idx])));
float p = nv / (1.0f + exp(-acc));
p += simd_shuffle_xor(p, 1);
p += simd_shuffle_xor(p, 2);
if (h == 0) mixed[(ulong)row * D + jp] = T(p / float(H));
float c[H];
for (int hh = 0; hh < H; ++hh) c[hh] = simd_sum(nv * float(winj[(ulong)hh * (H * D) + idx]));
if (thread_index_in_simdgroup == 0) for (int hh = 0; hh < H; ++hh) part[simdgroup_index_in_threadgroup][hh] = c[hh];
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < uint(H)) {
    float s = 0.0f;
    for (int i = 0; i < TGS / 32; ++i) s += part[i][tid];
    uint tgp = threadgroup_position_in_grid.x % (H * D / TGS);
    injp[((ulong)row * (H * D / TGS) + tgp) * H + tid] = s;
}

"""#
    static let hc_up_mix_sg = #"""
// hyper-connection tail, ONE SIMDGROUP PER OUTPUT COLUMN jp: the 4 rows (h = 0..3) of the 8-bit up-projection for column jp
// (4 x R bytes) are read as H*R/4 consecutive uint32 words spread over the 32 lanes (coalesced), so the 3.3 MB matrix streams
// at bandwidth with 8x the parallelism of the thread-per-output kernel.
//   sd[k]    = silu((sum_s down[row, s, k]) / H)            k < R   (DS split-K partials; DS = 1: plain [rows, R])   staged per threadgroup
//   u[h]     = sum_k sd[k] * (s*q + b)[h*D + jp, k]
//   mixed[jp]= mean_h sigmoid(u[h]) * normed[h*D + jp]
//   injp[row, tg, hh] = partial over this threadgroup's columns of sum_h normed[h*D+jp] * winj[hh, h*D+jp]    (P = D*32/TGS per row)
// grid: rows * D * 32 threads, threadgroup TGS (TGS/32 columns per threadgroup). template T, H, D, R, GS, TGS, DS.  Requires R % 128 == 0, H <= 8.
uint sgi = thread_position_in_grid.x / 32;
uint lane = thread_index_in_simdgroup;
uint tid = thread_index_in_threadgroup;
uint row = sgi / D, jp = sgi % D;
constexpr int WPR = R / 4;                 // uint32 words per row
constexpr int NW = H * WPR / 32;           // words per lane
constexpr int NG = R / GS;
threadgroup float sd[R];
threadgroup float sdsum[NG];
threadgroup float part[TGS / 32][H];
for (uint k = tid; k < uint(R); k += TGS) {
    float v = 0.0f;
    for (int s = 0; s < DS; ++s) v += float(down[((ulong)row * DS + s) * R + k]);
    v /= hcf[0];
    sd[k] = v / (1.0f + exp(-v));
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < uint(NG)) { float s = 0.0f; for (int k = 0; k < GS; ++k) s += sd[tid * GS + k]; sdsum[tid] = s; }
threadgroup_barrier(mem_flags::mem_threadgroup);
float acc[H];
for (int h = 0; h < H; ++h) acc[h] = 0.0f;
for (int i = 0; i < NW; ++i) {
    int w = lane + 32 * i;
    int h = w / WPR, kw = w % WPR;
    ulong ridx = (ulong)h * D + jp;
    uint32_t q = uw[ridx * WPR + kw];
    int k0 = kw * 4;
    const threadgroup float* sp = sd + k0;
    float dq = sp[0] * float(q & 0xffu) + sp[1] * float((q >> 8) & 0xffu) + sp[2] * float((q >> 16) & 0xffu) + sp[3] * float(q >> 24);
    float sc = float(us[ridx * NG + k0 / GS]);
    float c = sc * dq;
    for (int hh = 0; hh < H; ++hh) acc[hh] += (hh == h) ? c : 0.0f;
}
float u[H];
for (int h = 0; h < H; ++h) {
    float t = simd_sum(acc[h]);
    ulong ridx = (ulong)h * D + jp;
    float bt = 0.0f;
    for (int g = 0; g < NG; ++g) bt += float(ub[ridx * NG + g]) * sdsum[g];
    u[h] = t + bt;
}
float nv = (lane < uint(H)) ? float(normed[(ulong)row * (H * D) + lane * D + jp]) : 0.0f;
if (lane == 0) {
    float p = 0.0f;
    for (int h = 0; h < H; ++h) p += float(normed[(ulong)row * (H * D) + h * D + jp]) / (1.0f + exp(-u[h]));
    mixed[(ulong)row * D + jp] = T(p / float(H));
}
for (int hh = 0; hh < H; ++hh) {
    float wv = (lane < uint(H)) ? nv * float(winj[(ulong)hh * (H * D) + lane * D + jp]) : 0.0f;
    float c = simd_sum(wv);
    if (lane == 0) part[simdgroup_index_in_threadgroup][hh] = c;
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < uint(H)) {
    float s = 0.0f;
    for (int i = 0; i < TGS / 32; ++i) s += part[i][tid];
    constexpr int P = D * 32 / TGS;
    uint tgp = threadgroup_position_in_grid.x % P;
    injp[((ulong)row * P + tgp) * H + tid] = s;
}

"""#
    static let idx_relu_sum = #"""
// P019 unit 6: the QSA indexer's head reduction, fused. The graph form
//     scores = maximum(raw, 0).sum(axis: 2) / sqrt(headDim)
// runs three passes over raw [B,S,H,N] float32 -- at a 4096-row chunk over 135k of kv that tensor is 2.2 GB, so the
// relu alone reads and writes it before the sum reads it again. This computes out[b,s,n] = sum_h max(raw[b,s,h,n],0) * SCALE
// in ONE pass: read 2.2 GB, write 0.55 GB. The four head terms are summed in the same order as sum(axis: 2), so the
// result is bit-identical.
// It also applies the row's VISIBILITY predicate, which is pure arithmetic -- block n is visible to row s iff
//     n*RATIO + RATIO-1 <= kvLen - S + s
// -- so the (1,S,N) bool tensor the graph form built and the separate `which` pass over the 553 MB scores both disappear.
// params int32 [N, H, S, kvLen, ratio, apply_visibility, block_offset]  (block_offset lets a caller reduce a SLICE of the
// block axis and still apply visibility, so the (B,S,H,N) tensor never has to exist in full); raw float32 [B,S,H,N]; scale float32 [1] -> out float32 [B,S,N]
// grid: (B*S*ceil(N/VEC), 1, 1). template VEC.
int N = params[0], H = params[1], S = params[2], kvLen = params[3], RATIO = params[4], VIS = params[5], NOFF = params[6];
uint nblk = uint((N + VEC - 1) / VEC);
uint gid = thread_position_in_grid.x;
uint row = gid / nblk;
int c = int(gid % nblk) * VEC;
int limit = VIS != 0 ? (kvLen - S + int(row % uint(S))) : 0x7fffffff;   // row = b*S + s
const device T* p = raw + (ulong)row * (ulong)H * (ulong)N + c;
float acc[VEC];
for (int i = 0; i < VEC; ++i) acc[i] = 0.0f;
if (c + VEC <= N) {
    for (int h = 0; h < H; ++h) {
        const device T* ph = p + (ulong)h * (ulong)N;
        for (int i = 0; i < VEC; ++i) acc[i] += max(float(ph[i]), 0.0f);
    }
    device float* o = out + (ulong)row * (ulong)N + c;
    for (int i = 0; i < VEC; ++i) o[i] = ((NOFF + c + i) * RATIO + RATIO - 1 <= limit) ? acc[i] / scale[0] : -INFINITY;
} else {
    for (int h = 0; h < H; ++h) {
        const device T* ph = p + (ulong)h * (ulong)N;
        for (int i = 0; i < VEC; ++i) if (c + i < N) acc[i] += max(float(ph[i]), 0.0f);
    }
    for (int i = 0; i < VEC; ++i) if (c + i < N) out[(ulong)row * (ulong)N + c + i] = ((NOFF + c + i) * RATIO + RATIO - 1 <= limit) ? acc[i] / scale[0] : -INFINITY;
}

"""#
    static let idx_score_fused = #"""
// P020 unit 2: the QSA indexer's SCORE, fused end to end.
//   scores[b,s,n] = sum_h max( q[b,s,h,:] . pooled[b,n,:] , 0 ) / sqrt(D)      (with the visibility predicate)
// The shipped chain casts q and pooled to float32, runs ONE matmul into a (B,S,H,N) float32 tensor -- 2.21 GB at a
// 4096-row chunk over 135k of kv -- and then reads it back to relu-and-sum it (P019 unit 6 made that one pass instead
// of four, but the tensor still has to be written and read: matmul 10.3 ms + reduce 10.8 ms per layer-chunk).
// Here the head reduction happens in REGISTERS, so the intermediate never exists: read q (4 MB) and pooled (8.6 MB),
// write the 553 MB of scores, and nothing else.
// The products are bf16 x bf16 accumulated in float32, which is EXACT for the same reason the float32 matmul is: a
// bf16 x bf16 product is exact in float32, and both sides are bf16 in memory (the shipped path's `.asType(.float32)`
// is a lossless widening, not a precision gain). What differs from the shipped chain is the ORDER of the 128-term
// accumulation, i.e. the last ulp -- REFUT-ENG-008 refuted a bf16 OUTPUT, not a bf16 product.
// q [B,S,H,D] T, pooled [B,N,D] T, params int32 [N, S, kvLen, RATIO, VIS], scale float32 [1] -> out [B,S,N] float32
// template T, D, H, MI, NI (tile = 8*MI rows x 8*NI blocks). One simdgroup per head: threadgroup (32*H, 1, 1).
// grid ((B * ceil(S/TM) * ceil(N/TN)) * 32*H, 1, 1)
constexpr int TM = 8 * MI, TN = 8 * NI;
int N = params[0], S = params[1], kvLen = params[2], RATIO = params[3], VIS = params[4];
uint tg = threadgroup_position_in_grid.x;
uint h = thread_position_in_threadgroup.x / 32;          // one simdgroup per head
uint lane = thread_position_in_threadgroup.x % 32;
uint tid = thread_position_in_threadgroup.x;

int rowTiles = (S + TM - 1) / TM, colTiles = (N + TN - 1) / TN;
int b = int(tg) / (rowTiles * colTiles);
int rest = int(tg) % (rowTiles * colTiles);
// clamp the last tile back onto the array instead of guarding every load: the overlap recomputes rows/blocks that
// another tile also computes, with the same arithmetic in the same order, so the duplicate stores are identical
int s0 = min(int(rest % rowTiles) * TM, S - TM);
int n0 = min(int(rest / rowTiles) * TN, N - TN);

threadgroup T Bt[D * TN];                                 // pooled tile, transposed to (k, n)
threadgroup float C[H * TM * TN];

for (uint i = tid; i < uint(D * TN); i += 32 * H) {
    int k = int(i) / TN, n = int(i) % TN;
    Bt[k * TN + n] = pooled[((ulong)b * N + n0 + n) * D + k];
}
threadgroup_barrier(mem_flags::mem_threadgroup);

simdgroup_matrix<float, 8, 8> acc[MI][NI];
for (int i = 0; i < MI; ++i)
    for (int j = 0; j < NI; ++j) acc[i][j] = simdgroup_matrix<float, 8, 8>(0.0f);

const device T* qbase = q + (((ulong)b * S + s0) * H + h) * D;
for (int k0 = 0; k0 < D; k0 += 8) {
    simdgroup_matrix<T, 8, 8> A[MI], Bm[NI];
    for (int i = 0; i < MI; ++i) simdgroup_load(A[i], qbase + (ulong)(i * 8) * H * D + k0, H * D);
    for (int j = 0; j < NI; ++j) simdgroup_load(Bm[j], Bt + k0 * TN + j * 8, TN);
    for (int i = 0; i < MI; ++i)
        for (int j = 0; j < NI; ++j) simdgroup_multiply_accumulate(acc[i][j], A[i], Bm[j], acc[i][j]);
}
for (int i = 0; i < MI; ++i)
    for (int j = 0; j < NI; ++j) simdgroup_store(acc[i][j], C + h * TM * TN + (i * 8) * TN + j * 8, TN);
threadgroup_barrier(mem_flags::mem_threadgroup);

// head reduction in the SAME order as sum(axis: 2), then the visibility predicate and the scale (DIVIDE, never a
// reciprocal multiply -- the scores feed a top-K and a 1-ulp difference flips a near-tie, OBS-ENG-038)
for (uint o = tid; o < uint(TM * TN); o += 32 * H) {
    int r = int(o) / TN, c = int(o) % TN;
    float sum = 0.0f;
    for (int hh = 0; hh < H; ++hh) sum += max(C[hh * TM * TN + r * TN + c], 0.0f);
    int limit = VIS != 0 ? (kvLen - S + s0 + r) : 0x7fffffff;
    out[((ulong)b * S + s0 + r) * N + n0 + c] =
        ((n0 + c) * RATIO + RATIO - 1 <= limit) ? sum / scale[0] : -INFINITY;
}

"""#
    static let idx_score_fused2 = #"""
// P020 unit 2, variant 2 of the fused QSA indexer score (see idx_score_fused.metal for the semantics).
// Two changes the v1 H-sweep licensed (H=1/2/4 -> 6.10/5.23/7.44 ms: 4x the arithmetic costs +22%, so v1 was NOT
// compute-bound):
//   (a) the pooled tile is no longer staged in threadgroup memory. v1 staged it with consecutive threads reading
//       128 elements apart -- one 256-byte stride per thread, the worst possible coalescing. simdgroup_load reads
//       an 8x8 tile straight from device with transpose_matrix, so the staging, its barrier and its bank conflicts
//       all disappear.
//   (b) the head reduction happens in REGISTERS: each simdgroup owns all H heads for its own row block, so the
//       threadgroup scratch holds the REDUCED tile (TM x TN floats) instead of H copies of it.
// q [B,S,H,D] T, pooled [B,N,D] T, params int32 [N, S, kvLen, RATIO, VIS], scale float32 [1] -> out [B,S,N] float32
// template T, D, H, MI, NI, SG.  threadgroup (32*SG,1,1); tile = SG*8*MI rows x 8*NI blocks.
// grid ((B * ceil(S/TM) * ceil(N/TN)) * 32*SG, 1, 1)
constexpr int TMS = 8 * MI, TM = SG * TMS, TN = 8 * NI;
int N = params[0], S = params[1], kvLen = params[2], RATIO = params[3], VIS = params[4];
uint tg = threadgroup_position_in_grid.x;
uint tid = thread_position_in_threadgroup.x;
uint sg = tid / 32;

int rowTiles = (S + TM - 1) / TM, colTiles = (N + TN - 1) / TN;
int b = int(tg) / (rowTiles * colTiles);
int rest = int(tg) % (rowTiles * colTiles);
int s0 = min(int(rest % rowTiles) * TM, S - TM);
int n0 = min(int(rest / rowTiles) * TN, N - TN);

threadgroup float C[TM * TN];

simdgroup_matrix<float, 8, 8> acc[H][MI][NI];
for (int h = 0; h < H; ++h)
    for (int i = 0; i < MI; ++i)
        for (int j = 0; j < NI; ++j) acc[h][i][j] = simdgroup_matrix<float, 8, 8>(0.0f);

const device T* qbase = q + (((ulong)b * S + s0 + sg * TMS) * H) * D;
const device T* pbase = pooled + ((ulong)b * N + n0) * D;
for (int k0 = 0; k0 < D; k0 += 8) {
    simdgroup_matrix<T, 8, 8> A[H][MI], Bm[NI];
    for (int h = 0; h < H; ++h)
        for (int i = 0; i < MI; ++i)
            simdgroup_load(A[h][i], qbase + (ulong)(i * 8) * H * D + h * D + k0, H * D);
    for (int j = 0; j < NI; ++j)
        simdgroup_load(Bm[j], pbase + (ulong)(j * 8) * D + k0, D, ulong2(0, 0), true);
    for (int h = 0; h < H; ++h)
        for (int i = 0; i < MI; ++i)
            for (int j = 0; j < NI; ++j) simdgroup_multiply_accumulate(acc[h][i][j], A[h][i], Bm[j], acc[h][i][j]);
}
// relu and the head sum in registers, in the same order as sum(axis: 2)
for (int i = 0; i < MI; ++i) {
    for (int j = 0; j < NI; ++j) {
        simdgroup_matrix<float, 8, 8> r;
        thread auto& re = r.thread_elements();
        for (int e = 0; e < 2; ++e) {
            float s = 0.0f;
            for (int h = 0; h < H; ++h) s += max(acc[h][i][j].thread_elements()[e], 0.0f);
            re[e] = s;
        }
        simdgroup_store(r, C + (sg * TMS + i * 8) * TN + j * 8, TN);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint o = tid; o < uint(TM * TN); o += 32 * SG) {
    int r = int(o) / TN, c = int(o) % TN;
    int limit = VIS != 0 ? (kvLen - S + s0 + r) : 0x7fffffff;
    out[((ulong)b * S + s0 + r) * N + n0 + c] =
        ((n0 + c) * RATIO + RATIO - 1 <= limit) ? C[o] / scale[0] : -INFINITY;
}

"""#
    static let idx_score_fused3 = #"""
// P020 unit 2, variant 3 of the fused QSA indexer score (semantics: idx_score_fused.metal).
// v2 measured the register wall: 16 simdgroup accumulators per thread (32 floats/lane) runs, 32 spills and costs 35x.
// Keeping H separate accumulators therefore caps the output tile at H*MI*NI <= 16. Here the HEAD LOOP IS OUTSIDE the
// K loop, so only ONE head's accumulators are live at a time plus the running relu sum: 2*MI*NI matrices instead of
// H*MI*NI. The pooled tile is re-read once per head, which is free -- it is 8 KB per threadgroup and is shared by
// every row tile in flight.
// q [B,S,H,D] T, pooled [B,N,D] T, params int32 [N, S, kvLen, RATIO, VIS], scale float32 [1] -> out [B,S,N] float32
// template T, D, H, MI, NI, SG.  threadgroup (32*SG,1,1); tile = SG*8*MI rows x 8*NI blocks.
constexpr int TMS = 8 * MI, TM = SG * TMS, TN = 8 * NI;
int N = params[0], S = params[1], kvLen = params[2], RATIO = params[3], VIS = params[4];
uint tg = threadgroup_position_in_grid.x;
uint tid = thread_position_in_threadgroup.x;
uint sg = tid / 32;

int rowTiles = (S + TM - 1) / TM, colTiles = (N + TN - 1) / TN;
int b = int(tg) / (rowTiles * colTiles);
int rest = int(tg) % (rowTiles * colTiles);
int s0 = min(int(rest % rowTiles) * TM, S - TM);
int n0 = min(int(rest / rowTiles) * TN, N - TN);

threadgroup float C[TM * TN];

simdgroup_matrix<float, 8, 8> res[MI][NI];
for (int i = 0; i < MI; ++i)
    for (int j = 0; j < NI; ++j) res[i][j] = simdgroup_matrix<float, 8, 8>(0.0f);

const device T* qbase = q + (((ulong)b * S + s0 + sg * TMS) * H) * D;
const device T* pbase = pooled + ((ulong)b * N + n0) * D;
for (int h = 0; h < H; ++h) {
    simdgroup_matrix<float, 8, 8> acc[MI][NI];
    for (int i = 0; i < MI; ++i)
        for (int j = 0; j < NI; ++j) acc[i][j] = simdgroup_matrix<float, 8, 8>(0.0f);
    for (int k0 = 0; k0 < D; k0 += 8) {
        simdgroup_matrix<T, 8, 8> A[MI], Bm[NI];
        for (int i = 0; i < MI; ++i) simdgroup_load(A[i], qbase + (ulong)(i * 8) * H * D + h * D + k0, H * D);
        for (int j = 0; j < NI; ++j) simdgroup_load(Bm[j], pbase + (ulong)(j * 8) * D + k0, D, ulong2(0, 0), true);
        for (int i = 0; i < MI; ++i)
            for (int j = 0; j < NI; ++j) simdgroup_multiply_accumulate(acc[i][j], A[i], Bm[j], acc[i][j]);
    }
    for (int i = 0; i < MI; ++i)
        for (int j = 0; j < NI; ++j) {
            thread auto& re = res[i][j].thread_elements();
            thread auto& ae = acc[i][j].thread_elements();
            for (int e = 0; e < 2; ++e) re[e] += max(ae[e], 0.0f);
        }
}
for (int i = 0; i < MI; ++i)
    for (int j = 0; j < NI; ++j) simdgroup_store(res[i][j], C + (sg * TMS + i * 8) * TN + j * 8, TN);
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint o = tid; o < uint(TM * TN); o += 32 * SG) {
    int r = int(o) / TN, c = int(o) % TN;
    int limit = VIS != 0 ? (kvLen - S + s0 + r) : 0x7fffffff;
    out[((ulong)b * S + s0 + r) * N + n0 + c] =
        ((n0 + c) * RATIO + RATIO - 1 <= limit) ? C[o] / scale[0] : -INFINITY;
}

"""#
    static let moe_down = #"""
// q4_moe_down -- fused down projection over the K routed experts with the routing weights.
// inputs : h [T, K, I] (T), idx [T, K] int32, wts [T, K] (T), dw [E, D, I/8] uint32, ds/db [E, D, I/32] (T)
// output : y [T, D] (T) = sum_k wts[t,k] * down_{idx[t,k]} h[t,k]
// layout : tg.x = t, tg.y = row tile of 8 rows; simdgroup owns 4 rows; lane owns 16 inputs per 512 block.
// template: T, K, D, I
constexpr uint NSG = 2, ROWS = 4, VPT = 16, BLOCK = 512;
uint t = threadgroup_position_in_grid.x;
uint tile = threadgroup_position_in_grid.y;
uint sg = simdgroup_index_in_threadgroup;
uint lane = thread_index_in_simdgroup;
uint row0 = tile * (NSG * ROWS) + sg * ROWS;
const uint IW = I / 8, IG = I / 32;
float acc[ROWS];
for (uint r = 0; r < ROWS; ++r) acc[r] = 0.0f;
for (uint k = 0; k < K; ++k) {
    int e = idx[t * K + k];
    float wk = float(wts[t * K + k]);
    float part[ROWS];
    for (uint r = 0; r < ROWS; ++r) part[r] = 0.0f;
    for (uint kb = 0; kb < I; kb += BLOCK) {
        uint off = kb + lane * VPT;
        if (off < I) {
            float xv[VPT]; float xs = 0.0f;
            for (uint i = 0; i < VPT; ++i) { xv[i] = float(h[((ulong)t * K + k) * I + off + i]); xs += xv[i]; }
            uint g = off / 32;
            for (uint r = 0; r < ROWS; ++r) {
                ulong rowbase = ((ulong)e * D + row0 + r);
                const device uint32_t* wp = dw + rowbase * IW + off / 8;
                float d = 0.0f;
                for (uint p = 0; p < 2; ++p) {
                    uint32_t w = wp[p];
                    for (uint j = 0; j < 8; ++j) d += float((w >> (4 * j)) & 0xF) * xv[p * 8 + j];
                }
                part[r] += float(ds[rowbase * IG + g]) * d + float(db[rowbase * IG + g]) * xs;
            }
        }
    }
    for (uint r = 0; r < ROWS; ++r) acc[r] += wk * part[r];
}
for (uint r = 0; r < ROWS; ++r) {
    float s = simd_sum(acc[r]);
    if (lane == 0) y[(ulong)t * D + row0 + r] = T(s);
}

"""#
    static let moe_down_lane = #"""
// q4_moe_down_lane -- down projection, experts in parallel, ONE OUTPUT ROW PER LANE (short K = I inputs).
// inputs : h [T, K, I] (T), idx [T, K] int, dw [E, D, I/8] uint32, ds/db [E, D, I/32] (T)
// output : yk [T, K, D] (T) = down_{idx[t,k]} h[t,k]        (the combine kernel applies the routing weights and sums over k)
// grid   : tg.x = t*K + k, tg.y = tile of TGS rows; threadgroup TGS threads; h[t,k,:] staged in threadgroup memory.
// template: T, K, D, I, TGS
uint tg = threadgroup_position_in_grid.x;
uint tile = threadgroup_position_in_grid.y;
uint tid = thread_index_in_threadgroup;
uint t = tg / K, k = tg % K;
int e = idx[tg];
threadgroup float hs[I];
for (uint i = tid; i < uint(I); i += TGS) hs[i] = float(h[(ulong)tg * I + i]);
threadgroup_barrier(mem_flags::mem_threadgroup);
uint row = tile * TGS + tid;
if (row >= uint(D)) return;
ulong rowbase = (ulong)e * D + row;
const device uint4* wp = (const device uint4*)(dw + rowbase * (I / 8));
const device T* sp = ds + rowbase * (I / 32);
const device T* bp = db + rowbase * (I / 32);
float acc = 0.0f;
for (uint g = 0; g < uint(I / 32); ++g) {          // one 32-element group = one uint4 (4 words x 8 nibbles)
    uint4 w0 = wp[g];
    const threadgroup float* x = hs + g * 32;
    float d = 0.0f, xs = 0.0f;
    uint32_t ws[4] = {w0.x, w0.y, w0.z, w0.w};
    for (uint p = 0; p < 4; ++p) {
        uint32_t w = ws[p];
        for (uint j = 0; j < 8; ++j) { float xj = x[p * 8 + j]; d += float((w >> (4 * j)) & 0xF) * xj; xs += xj; }
    }
    acc += float(sp[g]) * d + float(bp[g]) * xs;
}
yk[(ulong)tg * D + row] = T(acc);

