    static let moe_down_lane_q8 = #"""
// q8_moe_down_lane -- the 8-bit g64 twin of moe_down_lane.metal. SAME structure, SAME k-order,
// SAME fp32 accumulation; only the unpack changes: 4 bytes per uint32 instead of 8 nibbles, and
// one scale group spans 64 elements (16 words = 4 uint4) instead of 32 (4 words = 1 uint4).
// inputs : h [T, K, I] (T), idx [T, K] int, dw [E, D, I/4] uint32, ds/db [E, D, I/64] (T)
// output : yk [T, K, D] (T) = down_{idx[t,k]} h[t,k]
// grid   : tg.x = t*K + k, tg.y = tile of TGS rows; threadgroup TGS threads; h[t,k,:] staged in threadgroup memory.
// template: T, K, D, I, TGS
uint tg = threadgroup_position_in_grid.x;
uint tile = threadgroup_position_in_grid.y;
uint tid = thread_index_in_threadgroup;
uint t = tg / K, k = tg % K;
int e = idx[tg];
threadgroup float hs[I];
for (uint i = tid; i < uint(I); i += TGS) hs[i] = float(h[(ulong)tg * I + i]);
threadgroup_barrier(mem_flags::mem_threadgroup);
uint row = tile * TGS + tid;
if (row >= uint(D)) return;
ulong rowbase = (ulong)e * D + row;
const device uint4* wp = (const device uint4*)(dw + rowbase * (I / 4));
const device T* sp = ds + rowbase * (I / 64);
const device T* bp = db + rowbase * (I / 64);
float acc = 0.0f;
for (uint g = 0; g < uint(I / 64); ++g) {          // one 64-element group = 4 uint4 (16 words x 4 bytes)
    const threadgroup float* x = hs + g * 64;
    float d = 0.0f, xs = 0.0f;
    for (uint q = 0; q < 4; ++q) {
        uint4 w0 = wp[g * 4 + q];
        uint32_t ws[4] = {w0.x, w0.y, w0.z, w0.w};
        for (uint p = 0; p < 4; ++p) {
            uint32_t w = ws[p];
            for (uint j = 0; j < 4; ++j) { float xj = x[q * 16 + p * 4 + j]; d += float((w >> (8 * j)) & 0xFF) * xj; xs += xj; }
        }
    }
    acc += float(sp[g]) * d + float(bp[g]) * xs;
}
yk[(ulong)tg * D + row] = T(acc);

"""#
    static let moe_down_lane_q8mr = #"""
// q8_moe_down_lane_mr -- the MULTI-ROW 8-bit g64 down lane. Same arithmetic as moe_down_lane_q8,
// same k-order, same fp32 accumulator; the only change is WHO reads the expert.
//
// WHY: the per-pair kernel launches one threadgroup per (row, expert slot) and re-reads that
// expert's weights for every row that selects it. Measured at 262144 with three trunk rows, the
// 30 (row, slot) pairs resolve to only 20.35 DISTINCT experts -- 32.1% of the weight traffic is a
// re-read (OBS-ENG-080). This body reads each distinct expert ONCE and applies it to every row that
// selected it. The threadgroup whose pair is not the FIRST occurrence of its expert exits at once.
//
// inputs : h [T,K,I] (T), idx [T,K] int, dw [E,D,I/4] uint32, ds/db [E,D,I/64] (T)
// output : yk [T,K,D] (T)
// grid   : tg.x = t*K + k (the pair), tg.y = tile of TGS rows; threadgroup TGS threads
// template: T, K, D, I, TGS, MR   (MR = the trunk row count, so slot[] and hs[] are sized at compile time)
uint p = threadgroup_position_in_grid.x;
uint tile = threadgroup_position_in_grid.y;
uint tid = thread_index_in_threadgroup;
int e = idx[p];
// FIRST-OCCURRENCE TEST, MADE ONCE PER THREADGROUP BY ONE THREAD. No sort and no host sync: the
// pair with the lowest index owns the expert and the rest return before touching a weight. Having
// every thread scan is what made the first build slower than the kernel it replaced -- the scan
// cost scales with (tiles x threads), the saving only with distinct experts.
threadgroup int tgFirst;
threadgroup int tgSlot[MR];
if (tid == 0) {
    int f = 1;
    for (uint q = 0; q < p; ++q) { if (idx[q] == e) { f = 0; break; } }
    tgFirst = f;
    for (uint r = 0; r < uint(MR); ++r) {
        tgSlot[r] = -1;
        for (uint k2 = 0; k2 < uint(K); ++k2) { if (idx[r * K + k2] == e) { tgSlot[r] = int(k2); break; } }
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tgFirst == 0) return;
int slot[MR];
for (uint r = 0; r < uint(MR); ++r) slot[r] = tgSlot[r];
threadgroup float hs[MR][I];
for (uint r = 0; r < uint(MR); ++r) {
    if (slot[r] < 0) continue;
    ulong base = (ulong)(r * K + uint(slot[r])) * I;
    for (uint i = tid; i < uint(I); i += TGS) hs[r][i] = float(h[base + i]);
}
threadgroup_barrier(mem_flags::mem_threadgroup);
uint row = tile * TGS + tid;
if (row >= uint(D)) return;
ulong rowbase = (ulong)e * D + row;
const device uint4* wp = (const device uint4*)(dw + rowbase * (I / 4));
const device T* sp = ds + rowbase * (I / 64);
const device T* bp = db + rowbase * (I / 64);
float acc[MR];
for (uint r = 0; r < uint(MR); ++r) acc[r] = 0.0f;
for (uint g = 0; g < uint(I / 64); ++g) {          // one 64-element group = 4 uint4 (16 words x 4 bytes)
    // d and xs accumulate across the WHOLE group and the scale is applied ONCE, which is what the
    // per-pair body does. Applying it per four-byte word would give the same value in exact
    // arithmetic and a different one in float32 -- and the acceptance of an MTP round is a function
    // of the exact logits (OBS-ENG-078 (8)), so "equivalent" is not good enough here.
    float d[MR], xs[MR];
    for (uint r = 0; r < uint(MR); ++r) { d[r] = 0.0f; xs[r] = 0.0f; }
    for (uint q = 0; q < 4; ++q) {
        uint4 w0 = wp[g * 4 + q];
        uint32_t ws[4] = {w0.x, w0.y, w0.z, w0.w};
        for (uint pp = 0; pp < 4; ++pp) {
            uint32_t w = ws[pp];
            for (uint j = 0; j < 4; ++j) {
                float wv = float((w >> (8 * j)) & 0xFF);
                uint xi = g * 64 + q * 16 + pp * 4 + j;
                for (uint r = 0; r < uint(MR); ++r) {
                    if (slot[r] < 0) continue;
                    float xj = hs[r][xi];
                    d[r] += wv * xj; xs[r] += xj;
                }
            }
        }
    }
    float sc = float(sp[g]), bi = float(bp[g]);
    for (uint r = 0; r < uint(MR); ++r) { if (slot[r] >= 0) acc[r] += sc * d[r] + bi * xs[r]; }
}
for (uint r = 0; r < uint(MR); ++r) {
    if (slot[r] < 0) continue;
    yk[(ulong)(r * K + uint(slot[r])) * D + row] = T(acc[r]);
}

"""#
    static let moe_down_lane_q8mr2 = #"""
// q8_moe_down_lane_mr2 -- the multi-row 8-bit g64 down lane, second form: ROWS output rows per
// thread. Same arithmetic, same k-order, same fp32 accumulator, same per-group scale as
// moe_down_lane_q8 and moe_down_lane_q8mr.
//
// WHY THIS EXISTS (P026 unit 1). The first multi-row down body (moe_down_lane_q8mr) reads each
// distinct expert once and applies it to every trunk row that selected it -- 32.1% fewer weight
// bytes -- and it LOST 2.31 ms/round doing it, at every TGS in {128,256,512,1024}. The cost is not
// occupancy: the gap is SMALLEST at the shipped TGS=256 and WORST at TGS=1024, where threadgroup
// memory pressure is lowest. It is the innermost trip count. Per-pair does 30 pairs x D x I
// element-ops; the multi-row form does 20 distinct x D x I x MR, i.e. it DOUBLES the innermost
// iterations (MR=3, only ~1.5 of the 3 slots live) to remove a third of the bytes. Its twin
// q8_moe_gate_up_mr survives the same doubling because it consumes TWO weight bytes (gate and up)
// per staged element AND hoists the weight word across ROWS output rows -- 4x this body's work per
// iteration.
//
// SO: hoist `hs` across ROWS output rows here too. One threadgroup-memory load of x now feeds ROWS
// weight bytes instead of one, which is exactly the ratio that makes the trade pay in the twin.
// `hs` is staged as T (bf16), not float: it is the same value read back from a bf16 device array,
// so the conversion is exact and the body stays BIT-IDENTICAL to the per-pair one, while halving
// the threadgroup allocation from 7680 B to 3840 B at MR=3.
//
// ROWS=1 reproduces moe_down_lane_q8mr exactly except for the staging dtype, which is what lets the
// two knobs be read apart.
//
// inputs : h [T,K,I] (T), idx [T,K] int, dw [E,D,I/4] uint32, ds/db [E,D,I/64] (T)
// output : yk [T,K,D] (T)
// grid   : tg.x = t*K + k (the pair), tg.y = tile of TGS*ROWS rows; threadgroup TGS threads
// template: T, K, D, I, TGS, MR, ROWS
uint p = threadgroup_position_in_grid.x;
uint tile = threadgroup_position_in_grid.y;
uint tid = thread_index_in_threadgroup;
int e = idx[p];
threadgroup int tgFirst;
threadgroup int tgSlot[MR];
if (tid == 0) {
    int f = 1;
    for (uint q = 0; q < p; ++q) { if (idx[q] == e) { f = 0; break; } }
    tgFirst = f;
    for (uint r = 0; r < uint(MR); ++r) {
        tgSlot[r] = -1;
        for (uint k2 = 0; k2 < uint(K); ++k2) { if (idx[r * K + k2] == e) { tgSlot[r] = int(k2); break; } }
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tgFirst == 0) return;
int slot[MR];
for (uint r = 0; r < uint(MR); ++r) slot[r] = tgSlot[r];
threadgroup T hs[MR][I];
for (uint r = 0; r < uint(MR); ++r) {
    if (slot[r] < 0) continue;
    ulong base = (ulong)(r * K + uint(slot[r])) * I;
    for (uint i = tid; i < uint(I); i += TGS) hs[r][i] = h[base + i];
}
threadgroup_barrier(mem_flags::mem_threadgroup);
uint row0 = (tile * TGS + tid) * uint(ROWS);
if (row0 >= uint(D)) return;
// The tail: D need not be a multiple of TGS*ROWS. `live` is a compile-time-shaped mask, not a
// dynamic loop bound, so the ROWS loops stay unrolled.
bool live[ROWS];
for (uint rr = 0; rr < uint(ROWS); ++rr) live[rr] = (row0 + rr) < uint(D);
const device uint4* wp[ROWS];
const device T* sp[ROWS];
const device T* bp[ROWS];
for (uint rr = 0; rr < uint(ROWS); ++rr) {
    ulong rb = (ulong)e * D + row0 + (live[rr] ? rr : 0);
    wp[rr] = (const device uint4*)(dw + rb * (I / 4));
    sp[rr] = ds + rb * (I / 64);
    bp[rr] = db + rb * (I / 64);
}
float acc[ROWS][MR];
for (uint rr = 0; rr < uint(ROWS); ++rr) for (uint r = 0; r < uint(MR); ++r) acc[rr][r] = 0.0f;
for (uint g = 0; g < uint(I / 64); ++g) {
    float d[ROWS][MR], xs[MR];
    for (uint rr = 0; rr < uint(ROWS); ++rr) for (uint r = 0; r < uint(MR); ++r) d[rr][r] = 0.0f;
    for (uint r = 0; r < uint(MR); ++r) xs[r] = 0.0f;
    for (uint q = 0; q < 4; ++q) {
        uint32_t ws[ROWS][4];
        for (uint rr = 0; rr < uint(ROWS); ++rr) {
            uint4 w0 = wp[rr][g * 4 + q];
            ws[rr][0] = w0.x; ws[rr][1] = w0.y; ws[rr][2] = w0.z; ws[rr][3] = w0.w;
        }
        for (uint pp = 0; pp < 4; ++pp) {
            for (uint j = 0; j < 4; ++j) {
                uint xi = g * 64 + q * 16 + pp * 4 + j;
                float wv[ROWS];
                for (uint rr = 0; rr < uint(ROWS); ++rr) wv[rr] = float((ws[rr][pp] >> (8 * j)) & 0xFF);
                // ONE threadgroup load of x, ROWS weight bytes consumed. This is the whole point.
                for (uint r = 0; r < uint(MR); ++r) {
                    if (slot[r] < 0) continue;
                    float xj = float(hs[r][xi]);
                    xs[r] += xj;
                    for (uint rr = 0; rr < uint(ROWS); ++rr) d[rr][r] += wv[rr] * xj;
                }
            }
        }
    }
    for (uint rr = 0; rr < uint(ROWS); ++rr) {
        float sc = float(sp[rr][g]), bi = float(bp[rr][g]);
        for (uint r = 0; r < uint(MR); ++r) { if (slot[r] >= 0) acc[rr][r] += sc * d[rr][r] + bi * xs[r]; }
    }
}
for (uint rr = 0; rr < uint(ROWS); ++rr) {
    if (!live[rr]) continue;
    for (uint r = 0; r < uint(MR); ++r) {
        if (slot[r] < 0) continue;
        yk[(ulong)(r * K + uint(slot[r])) * D + row0 + rr] = T(acc[rr][r]);
    }
}

