                for (uint j = 0; j < 8; ++j) d += float((w >> (4 * j)) & 0xF) * xv[p * 8 + j];
            }
            acc[r] += float(ds[rowbase * IG + g]) * d + float(db[rowbase * IG + g]) * xs;
        }
    }
