"""#
    static let moe_gateup = #"""
// q4_moe_gateup -- fused gate/up expert projections, affine 4-bit g32, small M.
// inputs : x [T, D] (T), idx [T, K] int32, gw/uw [E, I, D/8] uint32, gs/us gb/ub [E, I, D/32] (T)
// output : h [T, K, I] (T) = silu(gate) * up
// layout : threadgroup = NSG(2) simdgroups x 32 lanes; tg.x = t*K + k, tg.y = row tile of 8 rows;
//          each simdgroup owns 4 rows; each lane owns 16 consecutive inputs per 512-wide block.
// template: T, K, D, I, ROWS
constexpr uint NSG = 2, VPT = 16, BLOCK = 512;   // ROWS from template
uint tg = threadgroup_position_in_grid.x;        // t*K + k
uint tile = threadgroup_position_in_grid.y;
uint sg = simdgroup_index_in_threadgroup;
