// router top-K + softmax in one kernel. logits: [rows, LD] (LD >= E; column E may hold the shared-expert gate logit).
// one simdgroup per row (32 lanes x (E/32) values). Outputs: idx [rows, K] uint32, w [rows, K] T (softmax over the K
// selected logits, float math), sg [rows, 1] T = logits[row, E] (only if SG != 0). Ties: lowest expert index wins.
// grid: rows * 32 threads, threadgroup 32.  template: T, E, K, LD, SG.
uint row = thread_position_in_grid.x / 32;
uint lane = thread_index_in_simdgroup;
constexpr int PER = E / 32;
const device T* lr = logits + (ulong)row * LD;
float v[PER];
for (int i = 0; i < PER; ++i) v[i] = float(lr[lane * PER + i]);
float sel[K];
uint seli[K];
for (int k = 0; k < K; ++k) {
    float best = -INFINITY; int bi = 0;
    for (int i = 0; i < PER; ++i) if (v[i] > best) { best = v[i]; bi = i; }
    float gbest = simd_max(best);
    uint cand = (best == gbest) ? (lane * PER + bi) : 0xffffffffu;
    uint gi = simd_min(cand);
    sel[k] = gbest; seli[k] = gi;
    if (gi == lane * PER + bi) v[bi] = -INFINITY;
}
if (lane == 0) {
    float m = sel[0];
    float den = 0.0f;
    for (int k = 0; k < K; ++k) den += exp(sel[k] - m);
    for (int k = 0; k < K; ++k) { idx[row * K + k] = seli[k]; w[row * K + k] = T(exp(sel[k] - m) / den); }
    if (SG != 0) sg[row] = lr[E];
}

