    static let qsa_mma_gather = #"""
// P020 unit 18: the QSA gather attention in the simdgroup-MMA flash form BOUND-ENG-006 priced at 2.34x.
// One threadgroup per (b, kv-head, query row). The 12 query heads that share this kv-head are the M
// dimension of the matmul (padded to 16), so one simdgroup_load feeds 8 heads instead of one lane's 8
// elements -- OBS-ENG-045 located the shipped kernel's cost in load instructions per useful FLOP.
// One threadgroup covers ALL the selected keys, so there are no partials and no merge pass (the shipped
// PARTS=8 form writes and reads an 805 MB float32 partial tensor per layer-chunk).
// The K/V tile cannot be read in place: 8 consecutive keys are 2 blocks of R=4 that are not adjacent, so
// each BK-key tile is STAGED into threadgroup memory -- once as K, then the same buffer again as V.
// The online-softmax rescale of the accumulators is a DIAGONAL simdgroup matrix multiply (~12.5% more
// MMA work), which is what lets this stay a single pass over the keys.
// q [B,H,S,D] T (H = KVH*G), k/v [B,KVH,kcap,D] T, top [B,S,K] int32, params int32 [nBlocks,kvLen,kcap,offset],
// scale float32[1] -> o [B,H,S,D] T
// template T, D, H, KVH, S, R, K, SG, BK, G (= H/KVH, must be <= 16). grid (B*KVH*S*32*SG,1,1), threadgroup (32*SG,1,1).
constexpr int DS = D / SG, MI = 2, NI = DS / 8, KPS = BK / SG, NKEY = K * R + R - 1;
uint tg = threadgroup_position_in_grid.x;
uint tid = thread_position_in_threadgroup.x;
uint sg = tid / 32, lane = tid % 32;
uint s = tg % S, kvh = (tg / S) % KVH, b = tg / (S * KVH);
int nBlocks = params[0], kcap = params[2], offset = params[3];
int limit = offset + int(s);
