float scl = scale[0];

threadgroup T Qs[16 * D];
threadgroup T KV[BK * D];
threadgroup float Ss[16 * BK];
threadgroup float valid[BK];
threadgroup float rowm[16], rowl[16], rowf[16];
threadgroup float Dg[2 * 64];

// Q: rows 0..G-1 are this kv-head's query heads, the rest are zero padding
for (uint t = tid; t < 16 * D; t += 32 * SG) {
    uint r = t / D, d = t % D;
    Qs[t] = (r < G) ? q[(((ulong)(b * H + kvh * G + r) * S) + s) * D + d] : T(0);
}
