const device T* vb = v + (ulong)(b * KVH + kvh) * (ulong)kcap * D;
const device int* tp = top + (ulong)(b * S + s) * K;

for (int k0 = 0; k0 < NKEY; k0 += BK) {
    // resolve the BK key positions and stage K
    for (uint t = tid; t < BK; t += 32 * SG) {
        int kidx = k0 + int(t);
        int pos = -1;
        if (kidx < K * R) {
            int blk = tp[kidx / R];
            if (blk < nBlocks) { int p = blk * R + (kidx % R); if (p <= limit) pos = p; }
        } else {
            int p = rowTail + (kidx - K * R);
            if (p <= limit) pos = p;
        }
        valid[t] = (pos >= 0) ? float(pos) : -1.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint t = tid; t < BK * D; t += 32 * SG) {
        uint kk = t / D, d = t % D;
        int pos = int(valid[kk]);
        KV[t] = (pos >= 0) ? kb[(ulong)(GATHER ? pos : (k0 + int(kk))) * D + d] : T(0);   // GATHER=0: contiguous, DIAGNOSTIC
    }
