    // scores for this simdgroup's KPS keys, all 16 rows
    for (int kk = 0; kk < KPS; kk += 8) {
        simdgroup_matrix<float, 8, 8> sc[MI];
        for (int i = 0; i < MI; ++i) sc[i] = simdgroup_matrix<float, 8, 8>(0.0f);
        for (int d0 = 0; d0 < D; d0 += 8) {
            simdgroup_matrix<T, 8, 8> A[MI], Bm;
            for (int i = 0; i < MI; ++i) simdgroup_load(A[i], Qs + (i * 8) * D + d0, D);
            simdgroup_load(Bm, KV + (ulong)(sg * KPS + kk) * D + d0, D, ulong2(0, 0), true);
            for (int i = 0; i < MI; ++i) simdgroup_multiply_accumulate(sc[i], A[i], Bm, sc[i]);
        }
        for (int i = 0; i < MI; ++i) simdgroup_store(sc[i], Ss + (i * 8) * BK + sg * KPS + kk, BK);
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    // online softmax over this tile: one thread per row
    if (SKIP == 0 && tid < 16) {
        float m = rowm[tid];
        for (int j = 0; j < BK; ++j) if (valid[j] >= 0.0f) m = max(m, Ss[tid * BK + j] * scl);
        float f = (rowm[tid] <= -3.0e38f) ? 1.0f : fast::exp(rowm[tid] - m);
        float l = rowl[tid] * f, sum = 0.0f;
        for (int j = 0; j < BK; ++j) {
            float e = (valid[j] >= 0.0f) ? fast::exp(Ss[tid * BK + j] * scl - m) : 0.0f;
            Ss[tid * BK + j] = e; sum += e;
        }
        rowm[tid] = m; rowl[tid] = l + sum; rowf[tid] = f;
    }
    for (uint t = tid; t < 2 * 64; t += 32 * SG) Dg[t] = 0.0f;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < 16) Dg[(tid / 8) * 64 + (tid % 8) * 8 + (tid % 8)] = rowf[tid];
    // stage V into the same buffer
    for (uint t = tid; t < BK * D; t += 32 * SG) {
        uint kk = t / D, d = t % D;
        int pos = int(valid[kk]);
        KV[t] = (pos >= 0) ? vb[(ulong)(GATHER ? pos : (k0 + int(kk))) * D + d] : T(0);   // GATHER=0: contiguous, DIAGNOSTIC
