    }
    for (int kk = 0; kk < BK; kk += 8) {
        simdgroup_matrix<T, 8, 8> Pb[MI], Vm[NI];
        for (int i = 0; i < MI; ++i) {
            simdgroup_matrix<float, 8, 8> P;
            simdgroup_load(P, Ss + (i * 8) * BK + kk, BK);
            thread auto& pe = P.thread_elements();
            thread auto& be = Pb[i].thread_elements();
            for (int e = 0; e < 2; ++e) be[e] = T(pe[e]);
        }
        for (int j = 0; j < NI; ++j) simdgroup_load(Vm[j], KV + (ulong)kk * D + sg * DS + j * 8, D);
        for (int i = 0; i < MI; ++i)
            for (int j = 0; j < NI; ++j) simdgroup_multiply_accumulate(acc[i][j], Pb[i], Vm[j], acc[i][j]);
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}
// normalise and write out rows 0..G-1 only (8..15 of the second tile are padding)
threadgroup float* Ostage = (threadgroup float*)KV;          // 16 * DS floats per simdgroup fits BK*D*sizeof(T)
for (int i = 0; i < MI; ++i)
    for (int j = 0; j < NI; ++j)
        simdgroup_store(acc[i][j], Ostage + sg * (16 * DS) + (i * 8) * DS + j * 8, DS);
