}

"""#
    static let qsa_sdpa_gather = #"""
// QSA gather-attention for short decode blocks (S <= 8 rows): attends ONLY to the tokens of the indexer-selected blocks
// (top[b,s,:] = K block ids, ids >= nBlocks are invisible) plus the tail positions after the last complete block, instead of
// reading the whole kv with a boolean mask. One threadgroup per (b, h, s): BN = 32 simdgroups stride over the K*R + R virtual
// positions, online softmax per simdgroup in float, then the cross-simdgroup merge of MLX's sdpa_vector (same rounding).
// q [B,H,S,D] T, k/v [B,KVH,kcap,D] T (row-contiguous cache buffers), top [B,S,K] int32, params int32 [nBlocks, kvLen, kcap, offset],
// scale float32 [1]  ->  out [B,H,S,D] T.   template T, D, H, KVH, S, R, K.   grid (B*H*S*1024, 1, 1), threadgroup (1024, 1, 1)
constexpr int BN = 32, BD = 32, QK = D / BD;
uint tg = threadgroup_position_in_grid.x;
uint sg = simdgroup_index_in_threadgroup, lane = thread_index_in_simdgroup;
uint s = tg % S, bh = tg / S, h = bh % H, b = bh / H, kvh = h / (H / KVH);
int nBlocks = params[0], kcap = params[2], offset = params[3];
int limit = offset + int(s);
int rowTail = ((limit + 1) / R) * R;               // serial-step semantics: the row's own incomplete block is always visible
float scl = scale[0];
const device T* qp = q + ((ulong)bh * S + s) * D + lane * QK;
const device T* kb = k + (ulong)(b * KVH + kvh) * (ulong)kcap * D + lane * QK;
const device T* vb = v + (ulong)(b * KVH + kvh) * (ulong)kcap * D + lane * QK;
const device int* tp = top + (ulong)(b * S + s) * K;
float qv[QK], o[QK];
for (int j = 0; j < QK; ++j) { qv[j] = float(qp[j]) * scl; o[j] = 0.0f; }
float mxs = -3.0e38f, se = 0.0f;
const int NV = K * R + 16;                        // K*R selected positions + the row's own block [rowTail, limit] (< R + S <= 16)
for (int i = int(sg); i < NV; i += BN) {
    int pos; bool use;
    if (i < K * R) { int blk = tp[i / R]; pos = blk * R + (i % R); use = blk < nBlocks && pos < rowTail; }
    else { pos = rowTail + (i - K * R); use = pos <= limit; }
    if (!use) continue;
    const device T* kr = kb + (ulong)pos * D;
    const device T* vr = vb + (ulong)pos * D;
    float sc = 0.0f;
    for (int j = 0; j < QK; ++j) sc += qv[j] * float(kr[j]);
    sc = simd_sum(sc);
    float nm = max(mxs, sc);
    float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
    mxs = nm; se = se * f + e;
    for (int j = 0; j < QK; ++j) o[j] = o[j] * f + e * float(vr[j]);
}
threadgroup float maxs[BN], sums[BN], outs[BN * BD];
if (lane == 0) { maxs[sg] = mxs; sums[sg] = se; }
threadgroup_barrier(mem_flags::mem_threadgroup);
float m2 = maxs[lane];
float nm2 = simd_max(m2);
float f2 = fast::exp(m2 - nm2);
float tot = simd_sum(sums[lane] * f2);
for (int j = 0; j < QK; ++j) {
    outs[lane * BD + sg] = o[j];
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float r = simd_sum(outs[sg * BD + lane] * f2);
    o[j] = tot == 0.0f ? r : r / tot;
    threadgroup_barrier(mem_flags::mem_threadgroup);
