        // flight instead of one. REFUT (unit 6a): the load WIDTH is already optimal (vec<T,VW> is exactly 1.00x), and
        // REFUT-ENG-006 showed the traffic is not binding -- what is left is load LATENCY.
        vec<T, VW> kv[R][QK / VW], vv[R][QK / VW];
