            sc[r] = simd_sum(s);
        }
        for (int r = 0; r < R; ++r) {
            const device vec<T, VW>* vr = (const device vec<T, VW>*)(vb + (ulong)(base + r) * D);
            for (int j = 0; j < QK / VW; ++j) vv[r][j] = vr[j];
