        }
    } else {
        for (int r = 0; r < rmax; ++r) {
        const device T* kr = kb + (ulong)(base + r) * D;
        const device T* vr = vb + (ulong)(base + r) * D;
        float sc = 0.0f;
        for (int j = 0; j < QK; ++j) sc += qv[j] * float(kr[j]);
        sc = simd_sum(sc);
        float nm = max(mxs, sc);
        float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
        mxs = nm; se = se * f + e;
        for (int j = 0; j < QK; ++j) o[j] = o[j] * f + e * float(vr[j]);
        }
    }
