    for (int pos = rowTail; pos <= limit; ++pos) {
        const device T* kr = kb + (ulong)pos * D;
        const device T* vr = vb + (ulong)pos * D;
        float sc = 0.0f;
        for (int j = 0; j < QK; ++j) sc += qv[j] * float(kr[j]);
        sc = simd_sum(sc);
        float nm = max(mxs, sc);
        float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
        mxs = nm; se = se * f + e;
        for (int j = 0; j < QK; ++j) o[j] = o[j] * f + e * float(vr[j]);
    }
}
ulong pidx = ((ulong)(b * H + h) * S + s) * PARTS + part;
for (int j = 0; j < QK; ++j) po[pidx * D + lane * QK + j] = o[j];
if (lane == 0) { pm[pidx] = mxs; pl[pidx] = se; }

