    static let qsa_sdpa_gather_gqa_part_vec = #"""
// P020 unit 6: the block-loop gather kernel with VECTORISED K/V loads. The lane's QK = D/32 contiguous elements are
// 16-byte aligned (row stride D*sizeof(T) is a multiple of 16), so ONE vec<T,VW> load replaces VW scalar 2-byte loads.
// REFUT-ENG-006 refuted the scatter, the row-tile union and threadgroup staging as the reason this kernel is off its
// roofs, and the ablation put 71.7% of it in the LOOP -- load ISSUE COUNT is the one term none of those tests moved.
// Same arithmetic in the same order as qsa_sdpa_gather_gqa_part_blk.metal, so the result is bit-identical.
// extra template: VW (vector width in elements), VT (the vector type).
// QSA gather-attention, GQA-shared, BLOCK-LOOP variant with an unrolled whole-block path (P019 unit 4 + unit 8). Identical semantics to qsa_sdpa_gather_gqa_part.metal:
// one threadgroup per (b, kvh, s, part), G = H/KVH simdgroups (one query head each), lanes split D.
// The difference is the loop: the position loop loaded top[i/R] on EVERY position (R-fold redundant device traffic, an
// integer divide and a branch per position); here the loop walks the SELECTED BLOCKS and the R positions inside each,
// so the block id is read once per block and the visibility test is hoisted out of the R positions.
// The part split is BLOCK-aligned rather than position-aligned, so the online-softmax merge partitions the same set of
// positions differently -- exact in the same sense (the merge is exact for any partition), bitwise different in the last ulp.
// q [B,H,S,D] T, k/v [B,KVH,kcap,D] T, top [B,S,K] int32, params int32 [nBlocks, kvLen, kcap, offset], scale float32 [1]
// -> po [B,H,S,PARTS,D] float32, pm/pl [B,H,S,PARTS] float32
// template T, D, H, KVH, S, R, K, PARTS.   grid (B*KVH*S*PARTS*32, G, 1), threadgroup (32, G, 1)
constexpr int G = H / KVH, QK = D / 32;
uint tgx = threadgroup_position_in_grid.x;
uint g = thread_position_in_threadgroup.y, lane = thread_index_in_simdgroup;
uint part = tgx % PARTS, s = (tgx / PARTS) % S, bk = tgx / (PARTS * S), kvh = bk % KVH, b = bk / KVH;
uint h = kvh * G + g;
int nBlocks = params[0], kcap = params[2], offset = params[3];
int limit = offset + int(s);
int rowTail = ((limit + 1) / R) * R;
float scl = scale[0];
const device T* qp = q + ((ulong)(b * H + h) * S + s) * D + lane * QK;
const device T* kb = k + (ulong)(b * KVH + kvh) * (ulong)kcap * D + lane * QK;
const device T* vb = v + (ulong)(b * KVH + kvh) * (ulong)kcap * D + lane * QK;
const device int* tp = top + (ulong)(b * S + s) * K;
float qv[QK], o[QK];
for (int j = 0; j < QK; ++j) { qv[j] = float(qp[j]) * scl; o[j] = 0.0f; }
float mxs = -3.0e38f, se = 0.0f;
int nb0 = (int(part) * K) / PARTS, nb1 = (int(part) + 1) * K / PARTS;
for (int bi = nb0; bi < nb1; ++bi) {
    int blk = tp[bi];
    if (blk >= nBlocks) continue;
    int base = blk * R;
    if (base >= rowTail) continue;
    int rmax = min(R, rowTail - base);
    // the common case is a WHOLE block: give it a compile-time bound so the R positions unroll (rmax is dynamic only
    // for the block that straddles rowTail, which happens at most once per row)
    if (rmax == R) {
        for (int r = 0; r < R; ++r) {
            const device vec<T, VW>* kr = (const device vec<T, VW>*)(kb + (ulong)(base + r) * D);
            const device vec<T, VW>* vr = (const device vec<T, VW>*)(vb + (ulong)(base + r) * D);
            vec<T, VW> kv[QK / VW], vv[QK / VW];
            for (int j = 0; j < QK / VW; ++j) kv[j] = kr[j];
            float sc = 0.0f;
            for (int j = 0; j < QK / VW; ++j)
                for (int c = 0; c < VW; ++c) sc += qv[j * VW + c] * float(kv[j][c]);
            sc = simd_sum(sc);
            for (int j = 0; j < QK / VW; ++j) vv[j] = vr[j];
            float nm = max(mxs, sc);
            float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
            mxs = nm; se = se * f + e;
            for (int j = 0; j < QK / VW; ++j)
                for (int c = 0; c < VW; ++c) o[j * VW + c] = o[j * VW + c] * f + e * float(vv[j][c]);
        }
    } else {
