        const device T* kr = kb + (ulong)(base + r) * D;
        const device T* vr = vb + (ulong)(base + r) * D;
        float sc = 0.0f;
        for (int j = 0; j < QK; ++j) sc += qv[j] * float(kr[j]);
        sc = simd_sum(sc);
        float nm = max(mxs, sc);
        float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
        mxs = nm; se = se * f + e;
        for (int j = 0; j < QK; ++j) o[j] = o[j] * f + e * float(vr[j]);
        }
    }
}
if (part == PARTS - 1) {                       // the row's own incomplete block: at most R - 1 positions
    for (int pos = rowTail; pos <= limit; ++pos) {
        const device T* kr = kb + (ulong)pos * D;
        const device T* vr = vb + (ulong)pos * D;
        float sc = 0.0f;
        for (int j = 0; j < QK; ++j) sc += qv[j] * float(kr[j]);
        sc = simd_sum(sc);
        float nm = max(mxs, sc);
        float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
        mxs = nm; se = se * f + e;
        for (int j = 0; j < QK; ++j) o[j] = o[j] * f + e * float(vr[j]);
    }
}
ulong pidx = ((ulong)(b * H + h) * S + s) * PARTS + part;
for (int j = 0; j < QK; ++j) po[pidx * D + lane * QK + j] = o[j];
if (lane == 0) { pm[pidx] = mxs; pl[pidx] = se; }

"""#
    static let qsa_sdpa_gather_pipe = #"""
// P099: the S = 1 gather kernel (qsa_sdpa_gather / its ragged twin) with its per-simdgroup chain SOFTWARE-PIPELINED.
// The chain is 2064 / 32 ~ 65 dependent rounds per simdgroup, each a block-id load, a K row, a V row, then the
// online-softmax step -- latency-bound (the single kernel reads 178 us per layer at B = 8 for 34 MB, 188 GB/s).
// Here the block ids, K rows and V rows of the next PF positions are loaded into registers before the current
// position's arithmetic runs, so PF rounds of memory latency overlap. The VALUES and the ORDER of every float
// operation are the shipped kernel's (same positions per simdgroup, same online softmax, same cross-simdgroup
// merge), so the output is BIT-IDENTICAL; only the schedule of the loads moves.
// RG = 0: params int32 [nBlocks, kvLen, kcap, offset] (serial);  RG = 1: params [B, 0, kcap, 0] ++ offset[B] ++ nBlocks[B] (ragged, S = 1)
// template T, D, H, KVH, S, R, K, PF, RG.   grid (B*H*S*1024, 1, 1), threadgroup (1024, 1, 1)
constexpr int BN = 32, BD = 32, QK = D / BD;
uint tg = threadgroup_position_in_grid.x;
uint sg = simdgroup_index_in_threadgroup, lane = thread_index_in_simdgroup;
uint s = tg % S, bh = tg / S, h = bh % H, b = bh / H, kvh = h / (H / KVH);
int kcap = params[2];
int nBlocks, offset;
if (RG) { int Bn = params[0]; offset = params[4 + int(b)]; nBlocks = params[4 + Bn + int(b)]; }
else { nBlocks = params[0]; offset = params[3]; }
int limit = offset + int(s);
int rowTail = ((limit + 1) / R) * R;
float scl = scale[0];
const device T* qp = q + ((ulong)bh * S + s) * D + lane * QK;
const device T* kb = k + (ulong)(b * KVH + kvh) * (ulong)kcap * D + lane * QK;
const device T* vb = v + (ulong)(b * KVH + kvh) * (ulong)kcap * D + lane * QK;
const device int* tp = top + (ulong)(b * S + s) * K;
float qv[QK], o[QK];
for (int j = 0; j < QK; ++j) { qv[j] = float(qp[j]) * scl; o[j] = 0.0f; }
float mxs = -3.0e38f, se = 0.0f;
const int NV = K * R + 16;
// the ring: PF slots, slot t holds position i + t*BN of the current window. The slot index is a compile-time constant
// everywhere (the t-loops unroll over the template PF) and no slot is addressed through a pointer or a macro: a runtime
// index or a thread pointer puts the ring in memory (the first draft ran 20x slower), and the embedded-source generator
// doubles backslashes, so a line-continued macro cannot be used here. The issue body is therefore written out twice.
T kbuf[PF][QK], vbuf[PF][QK];
bool ubuf[PF];
#pragma clang loop unroll(full)
for (int t = 0; t < PF; ++t) {
        {
            int ip_ = int(sg) + t * BN;
            if (ip_ >= NV) { ubuf[t] = false; }
            else {
                int pos_; bool use_;
                if (ip_ < K * R) { int blk_ = tp[ip_ / R]; pos_ = blk_ * R + (ip_ % R); use_ = blk_ < nBlocks && pos_ < rowTail; }
                else { pos_ = rowTail + (ip_ - K * R); use_ = pos_ <= limit; }
                ubuf[t] = use_;
                if (use_) {
                    const device T* kr_ = kb + (ulong)pos_ * D;
                    const device T* vr_ = vb + (ulong)pos_ * D;
                    for (int j = 0; j < QK; ++j) kbuf[t][j] = kr_[j];
                    for (int j = 0; j < QK; ++j) vbuf[t][j] = vr_[j];
                }
            }
        }
}
for (int i = int(sg); i < NV; i += BN * PF) {
#pragma clang loop unroll(full)
    for (int t = 0; t < PF; ++t) {
        int ip = i + t * BN;
        bool use = ubuf[t] && ip < NV;
        float kr[QK], vr[QK];
        for (int j = 0; j < QK; ++j) { kr[j] = float(kbuf[t][j]); vr[j] = float(vbuf[t][j]); }
        // refill this slot for the next window before the math
        {
            int ip_ = ip + PF * BN;
            if (ip_ >= NV) { ubuf[t] = false; }
            else {
                int pos_; bool use_;
                if (ip_ < K * R) { int blk_ = tp[ip_ / R]; pos_ = blk_ * R + (ip_ % R); use_ = blk_ < nBlocks && pos_ < rowTail; }
                else { pos_ = rowTail + (ip_ - K * R); use_ = pos_ <= limit; }
                ubuf[t] = use_;
                if (use_) {
                    const device T* kr_ = kb + (ulong)pos_ * D;
                    const device T* vr_ = vb + (ulong)pos_ * D;
                    for (int j = 0; j < QK; ++j) kbuf[t][j] = kr_[j];
                    for (int j = 0; j < QK; ++j) vbuf[t][j] = vr_[j];
                }
            }
        }
        if (use) {
            float sc = 0.0f;
            for (int j = 0; j < QK; ++j) sc += qv[j] * kr[j];
            sc = simd_sum(sc);
            float nm = max(mxs, sc);
            float f = fast::exp(mxs - nm), e = fast::exp(sc - nm);
            mxs = nm; se = se * f + e;
            for (int j = 0; j < QK; ++j) o[j] = o[j] * f + e * vr[j];
        }
    }
}
threadgroup float maxs[BN], sums[BN], outs[BN * BD];
if (lane == 0) { maxs[sg] = mxs; sums[sg] = se; }
threadgroup_barrier(mem_flags::mem_threadgroup);
float m2 = maxs[lane];
float nm2 = simd_max(m2);
float f2 = fast::exp(m2 - nm2);
float tot = simd_sum(sums[lane] * f2);
for (int j = 0; j < QK; ++j) {
    outs[lane * BD + sg] = o[j];
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float r = simd_sum(outs[sg * BD + lane] * f2);
    o[j] = tot == 0.0f ? r : r / tot;
    threadgroup_barrier(mem_flags::mem_threadgroup);
}
if (lane == 0) { for (int j = 0; j < QK; ++j) out[((ulong)bh * S + s) * D + sg * QK + j] = T(o[j]); }

