for (int j = 0; j < QK; ++j) { qv[j] = float(qp[j]) * scl; o[j] = 0.0f; }
float mxs = -3.0e38f, se = 0.0f;
int i0 = int(part) * NPP, i1 = min(NV, i0 + NPP);
for (int i = i0; i < i1; ++i) {
