// Exact top-K selection (K largest of n float32 scores per row, unordered, like argpartition) by 4-pass radix select on the
// monotonic 32-bit key of each score. One threadgroup per row; TG threads stride over the row (n <= any size), 256-bin
// threadgroup histograms per 8-bit digit from the MSB; thread 0 scans the bins from the top to find the digit that contains
// the K-th largest key. Output: every index whose key is above the threshold, plus the first (K - count_above) indices whose key
// equals it (ties at the boundary are taken in index order; argpartition's tie choice is unspecified, so the SET may differ
// only when the K-th and (K+1)-th scores are exactly equal).
// scores [R, n] float32, params int32 [n, K] -> top [R, K] int32.   template K, TG.   grid (R*TG, 1, 1), threadgroup (TG, 1, 1)
uint row = threadgroup_position_in_grid.x;
uint tid = thread_index_in_threadgroup;
int n = params[0];
const device float* s = scores + (ulong)row * (ulong)n;
threadgroup atomic_uint hist[256];
threadgroup uint sel_bin, need_out;
threadgroup uint simdtot[8];
threadgroup uint sgt[32], seq[32];
uint prefix = 0u, mask = 0u, need = uint(K);
for (int d = 3; d >= 0; --d) {
    for (uint b = tid; b < 256u; b += TG) atomic_store_explicit(&hist[b], 0u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (int i = int(tid); i < n; i += int(TG)) {
        uint bits = as_type<uint>(s[i]);
        uint k = (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
        if ((k & mask) == prefix) atomic_fetch_add_explicit(&hist[(k >> (8 * d)) & 255u], 1u, memory_order_relaxed);
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    // parallel suffix scan from the top bin: thread t < 256 owns bin b = 255 - t; S(t) = sum of the bins above and including b.
    // The selected bin is the unique t with S(t-1) < need <= S(t) (S(-1) = 0). Barriers are uniform (outside the branches).
    uint v = 0u, inc = 0u;
    if (tid < 256u) {
        v = atomic_load_explicit(&hist[255u - tid], memory_order_relaxed);
        inc = simd_prefix_inclusive_sum(v);
        if ((tid & 31u) == 31u) simdtot[tid / 32u] = inc;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
