// increasing part number, the phase-2 candidate list is in increasing original id -- so phase 2's tie rule
// is the global one. Under the strict order (key desc, id asc) an element of the global top-K has fewer
// than K predecessors globally and therefore fewer than K inside its own part: the union of the per-part
// top-Ks contains the global top-K exactly, ties included.
// scores [R, SROW] float32, params int32 [n, K, OFS, SROW], ids [R, n] int32 (dummy when USEIDX=0)
//   -> top [R, K] int32.   template K, TG, USEIDX, PARTS, ROUNDS.  grid (R*TG,1,1), threadgroup (TG,1,1)
uint row = threadgroup_position_in_grid.x;
uint tid = thread_index_in_threadgroup;
int n = params[0], OFS = params[2], SROW = params[3];
// P026 unit 3: the part offset, computed HERE instead of by an MLX add on the caller's side. Phase 1
// is launched as R*PARTS threadgroups over the row reshaped to (R*PARTS, m), so this threadgroup's
// part number is row % PARTS and its part starts at that many rows of m. PARTS is a template
// constant, so the modulo folds at compile time for the PARTS=1 instantiation and vanishes.
// WHY IT MATTERS: the caller used to add a broadcast offset array to the (R,PARTS,K) ids, which is a
// whole extra MLX dispatch per selection -- twelve of them per token -- and this kernel's own header
// already recorded that "at S=1 a small MLX op costs ~20 us, which is most of what the split saves".
// The header said it; the caller did it anyway.
if (PARTS > 1) { OFS += int(row % uint(PARTS)) * n; }
const device float* s = scores + (ulong)row * (ulong)SROW;
// `ids` may be bound in the constant OR the device address space depending on its size, so it is
// indexed inline rather than through a typed pointer (a `const device int*` initialiser fails to compile
// for the small dummy of the USEIDX=0 instantiation).
ulong ixb = (ulong)row * (ulong)n;
threadgroup atomic_uint hist[256];
threadgroup uint sel_bin, need_out;
threadgroup uint simdtot[8];
threadgroup uint sgt[32], seq[32];
uint prefix = 0u, mask = 0u, need = uint(K);
// P026 unit 6, IN-SITU ABLATION (ROUNDS < 4 is TIMING ONLY -- the threshold is then a 8*ROUNDS-bit
// prefix and the selection is WRONG by construction, exactly like ENGINE_ABL_SKIP). It exists to
// PRICE the round count before an exact round-reducing body is built: OBS-ENG-083 (2) measured the
// survivors after each digit as 63125 / 46 / 1 / 1, so rounds d1 and d0 pay full threadgroup
// barriers to resolve 46 and then 1 element. ROUNDS=4 is the shipped body and is bit-identical to
// it -- the loop bound folds to the same constant and the guards below compile out.
for (int d = 3; d >= 4 - int(ROUNDS); --d) {
    for (uint b = tid; b < 256u; b += TG) atomic_store_explicit(&hist[b], 0u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (int i = int(tid); i < n; i += int(TG)) {
        uint bits = as_type<uint>(USEIDX ? s[ids[ixb + i]] : s[i]);
        uint k = (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
        if ((k & mask) == prefix) atomic_fetch_add_explicit(&hist[(k >> (8 * d)) & 255u], 1u, memory_order_relaxed);
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    uint v = 0u, inc = 0u;
    if (tid < 256u) {
        v = atomic_load_explicit(&hist[255u - tid], memory_order_relaxed);
        inc = simd_prefix_inclusive_sum(v);
        if ((tid & 31u) == 31u) simdtot[tid / 32u] = inc;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < 256u) {
        uint carry = 0u;
        for (uint g = 0; g < tid / 32u; ++g) carry += simdtot[g];
        uint S = inc + carry, Sprev = S - v;
        if (Sprev < need && need <= S) { sel_bin = 255u - tid; need_out = need - Sprev; }
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    prefix |= sel_bin << (8 * d);
    mask |= 0xFFu << (8 * d);
    need = need_out;
    threadgroup_barrier(mem_flags::mem_threadgroup);
}
uint T = prefix;
device int* o = top + (ulong)row * (ulong)K;
int chunk = (n + int(TG) - 1) / int(TG);
int i0 = int(tid) * chunk, i1 = min(n, i0 + chunk);
uint cgt = 0u, ceq = 0u;
for (int i = i0; i < i1; ++i) {
    uint bits = as_type<uint>(USEIDX ? s[ids[ixb + i]] : s[i]);
    uint k = (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
    cgt += (k > T) ? 1u : 0u; ceq += (k == T) ? 1u : 0u;
}
uint sgi2 = tid / 32u, lane = tid & 31u;
uint pg = simd_prefix_exclusive_sum(cgt), pe = simd_prefix_exclusive_sum(ceq);
uint tg_gt = simd_sum(cgt), tg_eq = simd_sum(ceq);
if (lane == 0u) { sgt[sgi2] = tg_gt; seq[sgi2] = tg_eq; }
threadgroup_barrier(mem_flags::mem_threadgroup);
uint cg = 0u, ce = 0u, total_gt = 0u;
for (uint g = 0; g < TG / 32u; ++g) { if (g < sgi2) { cg += sgt[g]; ce += seq[g]; } total_gt += sgt[g]; }
uint gbase = pg + cg, ebase = pe + ce;
for (int i = i0; i < i1; ++i) {
    uint bits = as_type<uint>(USEIDX ? s[ids[ixb + i]] : s[i]);
    uint k = (bits & 0x80000000u) ? ~bits : (bits | 0x80000000u);
    int outid = USEIDX ? ids[ixb + i] : (i + OFS);
    if (k > T) { if (ROUNDS == 4 || gbase < uint(K)) o[gbase] = outid; gbase++; }
    else if (k == T) { if (ebase < need && (ROUNDS == 4 || total_gt + ebase < uint(K))) o[total_gt + ebase] = outid; ebase++; }
}

"""#
    static let topk_select_reg = #"""
// q4_topk_select_reg -- the REGISTER-RESIDENT exact top-K. Same algorithm, same key transform, same
// strict order (key descending, index ascending), same output, as q4_topk_select_ix. It is
// BIT-IDENTICAL by construction: nothing about what is computed changes, only how many times the
// keys are read out of memory.
//
// WHY (P026 unit 5). The shipped body makes SIX full passes over n: four 8-bit radix passes, each
// re-reading every element to test `(k & mask) == prefix`, then a count pass and an emit pass. A
// one-shot in-situ witness on the real scores at 262144 (n=65536, K=512) reads the survivor counts
// after each digit as **d3=63125, d2=46, d1=1, d0=1**, with only 38 distinct values in the top 12
// bits of the whole row. So the first digit removes 3.7% of the work, the second does all of it, and
// **the last two passes scan 65536 elements to examine 46 and then 1** -- because a survivor test
// still has to touch every element to find the survivors.
//
// The fix is not a better digit schedule, it is to stop re-reading. At the shipped P=4 a part is
// 16384 elements over TG=1024 threads = CH=16 keys per thread, which is 16 registers; phase 2 is
// 2048 over 1024 = CH=2. So the ENTIRE working set fits in the register file of the threadgroup that
// is already selecting it. Read it ONCE, keep it, and run all four radix passes and both compaction
// passes out of registers: **one device pass instead of six.**
//
// Ownership is CONTIGUOUS (thread tid owns [tid*CH, tid*CH+CH)), which is exactly the assignment the
// shipped emit already uses for its ordered output, so the index order of the result is unchanged.
// The radix passes used a STRIDED assignment; a histogram is a count and does not care about the
// order it is accumulated in, so moving them onto the same contiguous chunks changes no bin.
//
// scores [R, SROW] float32, params int32 [n, K, OFS, SROW], ids [R, n] int32 (dummy when USEIDX=0)
//   -> top [R, K] int32.   template K, TG, USEIDX, PARTS, CH, FULL.  grid (R*TG,1,1), threadgroup (TG,1,1)
//   REQUIRES CH * TG >= n. FULL=1 asserts CH*TG == n exactly, which drops the per-element tail guard
//   and the register that held it -- at 1024 threads a core's register budget is ~52 words per
//   thread, so a whole CH-sized bool array is not free.
uint row = threadgroup_position_in_grid.x;
uint tid = thread_index_in_threadgroup;
int n = params[0], OFS = params[2], SROW = params[3];
const device float* s = scores + (ulong)row * (ulong)SROW;
if (PARTS > 1) { OFS += int(row % uint(PARTS)) * n; }
ulong ixb = (ulong)row * (ulong)n;
threadgroup atomic_uint hist[256];
threadgroup uint sel_bin, need_out;
threadgroup uint simdtot[8];
threadgroup uint sgt[32], seq[32];

// THE ONE DEVICE PASS. Everything after this reads kv[] and idv[].
int i0 = int(tid) * CH;
uint kv[CH];
int idv[CH];
for (uint j = 0; j < uint(CH); ++j) {
    int i = i0 + int(j);
    bool okj = FULL ? true : (i < n);
    int src = okj ? i : 0;
    if (USEIDX) { src = okj ? ids[ixb + src] : 0; idv[j] = src; }
    uint bits = as_type<uint>(s[src]);
    // A tail slot must never win a comparison or land in a histogram: 0u is the smallest key under
    // this transform, and every live key has the top bit set (positive floats keep it, negatives are
    // complemented into the low half but still... ) -- so the guards below test `live` explicitly
    // rather than relying on a sentinel.
    kv[j] = okj ? ((bits & 0x80000000u) ? ~bits : (bits | 0x80000000u)) : 0u;
}
#define LIVE(j) (FULL ? true : (i0 + int(j) < n))

uint prefix = 0u, mask = 0u, need = uint(K);
for (int d = 3; d >= 0; --d) {
    for (uint b = tid; b < 256u; b += TG) atomic_store_explicit(&hist[b], 0u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint j = 0; j < uint(CH); ++j) {
        if (LIVE(j) && (kv[j] & mask) == prefix)
            atomic_fetch_add_explicit(&hist[(kv[j] >> (8 * d)) & 255u], 1u, memory_order_relaxed);
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    uint v = 0u, inc = 0u;
    if (tid < 256u) {
        v = atomic_load_explicit(&hist[255u - tid], memory_order_relaxed);
        inc = simd_prefix_inclusive_sum(v);
        if ((tid & 31u) == 31u) simdtot[tid / 32u] = inc;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < 256u) {
        uint carry = 0u;
        for (uint g = 0; g < tid / 32u; ++g) carry += simdtot[g];
        uint S = inc + carry, Sprev = S - v;
        if (Sprev < need && need <= S) { sel_bin = 255u - tid; need_out = need - Sprev; }
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    prefix |= sel_bin << (8 * d);
    mask |= 0xFFu << (8 * d);
    need = need_out;
    threadgroup_barrier(mem_flags::mem_threadgroup);
}
uint T = prefix;
device int* o = top + (ulong)row * (ulong)K;
uint cgt = 0u, ceq = 0u;
for (uint j = 0; j < uint(CH); ++j) {
    if (!LIVE(j)) continue;
    cgt += (kv[j] > T) ? 1u : 0u; ceq += (kv[j] == T) ? 1u : 0u;
}
uint sgi2 = tid / 32u, lane = tid & 31u;
uint pg = simd_prefix_exclusive_sum(cgt), pe = simd_prefix_exclusive_sum(ceq);
uint tg_gt = simd_sum(cgt), tg_eq = simd_sum(ceq);
if (lane == 0u) { sgt[sgi2] = tg_gt; seq[sgi2] = tg_eq; }
threadgroup_barrier(mem_flags::mem_threadgroup);
uint cg = 0u, ce = 0u, total_gt = 0u;
for (uint g = 0; g < TG / 32u; ++g) { if (g < sgi2) { cg += sgt[g]; ce += seq[g]; } total_gt += sgt[g]; }
uint gbase = pg + cg, ebase = pe + ce;
for (uint j = 0; j < uint(CH); ++j) {
    if (!LIVE(j)) continue;
    int outid = USEIDX ? idv[j] : (i0 + int(j) + OFS);
    if (kv[j] > T) { o[gbase++] = outid; }
    else if (kv[j] == T) { if (ebase < need) o[total_gt + ebase] = outid; ebase++; }
}

